use super::*;

/// The record role a set of declaration attributes implies — `test` for a `#[cfg(test)]` gate.
///
/// The same judgement [`role_for`] makes, over the attributes alone, so the two cannot answer
/// differently for the same `#[cfg(test)]`.
pub(crate) fn role_of(attrs: &[String]) -> &'static str {
    role_for(&ModuleDecl {
        name: String::new(),
        vis: String::new(),
        line: String::new(),
        block: String::new(),
        docs: Vec::new(),
        attrs: attrs.to_vec(),
    })
}
